'use client'
import React,{useEffect,useMemo,useState} from 'react'
import {createClient} from '@/lib/supabase/client'
import {CARD_DECK,CHOICE_QUESTIONS,DRAW_WORDS,GAME_CATALOG,MIND_PROMPTS,TABOO_CARDS,TRIVIA,TRIVIA_CURATED_COUNT,TRUTH_DARES,GameDef} from '@/lib/gameCatalog'
import {ADVENTURES,ESCAPES} from '@/lib/adventures'
import DrawingBoard,{Stroke} from './DrawingBoard'
import {LiveAirHockey,LivePong,LiveSnakeDuo,LiveTurboRace,ReactionGame} from './MiniArcade'
import SoloGames from './SoloGames'

type Session={id:string;couple_id:string;game_type:string;mode:string;status:string;created_by:string;state:any;created_at:string;updated_at:string;expires_at:string}
type Turn={id:string;session_id:string;user_id:string;round_no:number;action_type:string;payload:any;created_at:string}

function hashIndex(id:string,n:number){let h=2166136261;for(const c of id){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return n?Math.abs(h)%n:0}
function gameBy(id:string){return GAME_CATALOG.find(g=>g.id===id)??GAME_CATALOG[0]}
function normalize(s:string){return s.trim().toLocaleLowerCase('es-PE').normalize('NFD').replace(/[\u0300-\u036f]/g,'')}

const VERSUS_IDS=new Set(['know-me','trivia-versus','reaction','pong','air-hockey','turbo-race'])
const COOP_IDS=new Set(['mind-meld','trivia-coop','puzzle','adventure','escape','snake-duo','block-drop'])
const ROUND_TARGETS:Record<string,number>={'know-me':5,'mind-meld':5,'would-you-rather':5,'likely':5,'either-or':8,'trivia-versus':7,'trivia-coop':7}
const ROUND_ACTION:Record<string,string>={'know-me':'choice','would-you-rather':'choice','likely':'choice','either-or':'choice','mind-meld':'text','trivia-versus':'trivia','trivia-coop':'trivia'}
function playStyle(g:GameDef){if(VERSUS_IDS.has(g.id))return 'versus';if(COOP_IDS.has(g.id))return 'coop';if(g.mode==='live')return 'live';return 'turns'}
function playLabel(g:GameDef){const k=playStyle(g);return k==='versus'?'⚔️ 1 VS 1':k==='coop'?'🤝 COOPERATIVO':g.mode==='live'?'⚡ EN VIVO':'❤️ POR TURNOS'}
function targetRounds(g:GameDef){return ROUND_TARGETS[g.id]||1}
function sessionRoundProgress(g:GameDef,ts:Turn[]){const action=ROUND_ACTION[g.id];const target=targetRounds(g);if(!action||target===1)return null;let completed=0;for(let r=1;r<=target;r++){const users=new Set(ts.filter(t=>t.action_type===action&&Number(t.payload?.round||1)===r).map(t=>t.user_id));if(users.size>=2)completed++;else break}return {completed,current:Math.min(target,completed+1),target}}
function currentRoundFor(g:GameDef,ts:Turn[]){return sessionRoundProgress(g,ts)?.current||1}
function turnBadge(s:Session,ts:Turn[],userId:string){const g=gameBy(s.game_type),action=ROUND_ACTION[g.id];if(action){const round=currentRoundFor(g,ts);const mine=ts.some(t=>t.user_id===userId&&t.action_type===action&&Number(t.payload?.round||1)===round);const prog=sessionRoundProgress(g,ts);if(prog&&prog.completed>=prog.target)return 'Listo para cerrar';return mine?'Esperando':'Tu turno'}const last=ts.at(-1)?.user_id;if(!last)return 'Tu turno';return last===userId?'Esperando':'Tu turno'}
function uniqueNewest(sessions:Session[]){const seen=new Set<string>();return sessions.filter(x=>{if(seen.has(x.game_type))return false;seen.add(x.game_type);return true})}
function sampleIndices(total:number,count:number,avoid:number[]=[]){const blocked=new Set(avoid);let pool=Array.from({length:total},(_,i)=>i).filter(i=>!blocked.has(i));if(pool.length<count)pool=Array.from({length:total},(_,i)=>i);for(let i=pool.length-1;i>0;i--){const a=new Uint32Array(1);crypto.getRandomValues(a);const j=a[0]%(i+1);[pool[i],pool[j]]=[pool[j],pool[i]]}return pool.slice(0,Math.min(count,total))}
function sampleTriviaIndices(count:number,avoid:number[]=[]){const blocked=new Set(avoid),curated=sampleIndices(Math.min(TRIVIA_CURATED_COUNT,TRIVIA.length),Math.min(3,count),avoid),generatedPool=Array.from({length:Math.max(0,TRIVIA.length-TRIVIA_CURATED_COUNT)},(_,i)=>i+TRIVIA_CURATED_COUNT).filter(i=>!blocked.has(i));for(let i=generatedPool.length-1;i>0;i--){const a=new Uint32Array(1);crypto.getRandomValues(a);const j=a[0]%(i+1);[generatedPool[i],generatedPool[j]]=[generatedPool[j],generatedPool[i]]}let picks=[...curated,...generatedPool.slice(0,Math.max(0,count-curated.length))];if(picks.length<count)picks=sampleIndices(TRIVIA.length,count,avoid);return picks.slice(0,count)}

type Wallet={coins:number;xp:number;level:number;pet_name?:string|null}

export default function GamesHub({coupleId,userId,partnerName='Tu compañero/a',onPoints}:{coupleId:string;userId:string;partnerName?:string;onPoints?:(n:number)=>void}){
 const s=useMemo(()=>createClient(),[])
 const [view,setView]=useState<'home'|'solo'|'catalog'|'pending'>('home');const [selected,setSelected]=useState<GameDef|null>(null);const [session,setSession]=useState<Session|null>(null);const [turns,setTurns]=useState<Turn[]>([]);const [pending,setPending]=useState<Session[]>([]);const [pendingTurns,setPendingTurns]=useState<Record<string,Turn[]>>({});const [presence,setPresence]=useState(false);const [filter,setFilter]=useState<'all'|'async'|'live'|'versus'|'coop'>('all');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [soundEnabled,setSoundEnabled]=useState(true);const [turnToast,setTurnToast]=useState('');const [lastFinished,setLastFinished]=useState<GameDef|null>(null);const [wallet,setWallet]=useState<Wallet|null>(null);const [walletError,setWalletError]=useState('')
 useEffect(()=>{try{setSoundEnabled(localStorage.getItem('nosotros-game-sound')!=='off')}catch{}},[])
 function playTurnSound(){if(!soundEnabled)return;try{const Ctx=(window.AudioContext||(window as any).webkitAudioContext);if(!Ctx)return;const ctx=new Ctx(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(660,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(880,ctx.currentTime+.16);gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.11,ctx.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.28);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.3);setTimeout(()=>ctx.close(),500)}catch{}}
 function alertPartnerTurn(){setTurnToast(`💌 ${partnerName} respondió. ¡Es tu turno!`);setTimeout(()=>setTurnToast(''),6000);navigator.vibrate?.([80,45,80]);playTurnSound();if(typeof Notification!=='undefined'&&Notification.permission==='granted'&&document.hidden){try{new Notification('Pandalandia · Tu turno 🐼',{body:`${partnerName} respondió una partida.`,tag:'nosotros-turn'})}catch{}}}
 async function enableAlerts(){setSoundEnabled(true);try{localStorage.setItem('nosotros-game-sound','on')}catch{};if(typeof Notification!=='undefined'&&Notification.permission==='default'){const result=await Notification.requestPermission();setMessage(result==='granted'?'Avisos activados mientras la app mantenga conexión.':'El navegador no concedió permiso para avisos.')}else setMessage('Sonido y vibración de turnos activados.')}
 function toggleSound(){const next=!soundEnabled;setSoundEnabled(next);try{localStorage.setItem('nosotros-game-sound',next?'on':'off')}catch{};setMessage(next?'Sonidos de juego activados.':'Sonidos de juego desactivados.')}
 async function loadWallet(){setWalletError('');const {data,error}=await s.from('pet_worlds').select('coins,xp,level,pet_name').eq('couple_id',coupleId).maybeSingle();if(error){setWalletError('No pudimos cargar tus recursos');return}if(!data){setWallet(null);return}setWallet({coins:Number(data.coins??0),xp:Number(data.xp??0),level:Number(data.level??1),pet_name:data.pet_name})}
 useEffect(()=>{loadPending();loadWallet();const ch=s.channel(`games-${coupleId}`,{config:{presence:{key:userId}}}).on('postgres_changes',{event:'*',schema:'public',table:'game_sessions',filter:`couple_id=eq.${coupleId}`},()=>loadPending()).on('postgres_changes',{event:'INSERT',schema:'public',table:'game_turns',filter:`couple_id=eq.${coupleId}`},payload=>{if(session&&payload.new?.session_id===session.id)loadTurns(session.id);if(payload.new?.user_id&&payload.new.user_id!==userId)alertPartnerTurn();loadPending()}).on('postgres_changes',{event:'*',schema:'public',table:'pet_worlds',filter:`couple_id=eq.${coupleId}`},()=>loadWallet()).on('presence',{event:'sync'},()=>{const st=ch.presenceState();setPresence(Object.values(st).flat().length>1)}).subscribe(async status=>{if(status==='SUBSCRIBED')await ch.track({user_id:userId,at:new Date().toISOString()})});return()=>{s.removeChannel(ch)}},[coupleId,userId,session?.id,soundEnabled])
 async function loadPending(){const {data}=await s.from('game_sessions').select('*').eq('couple_id',coupleId).in('status',['active','waiting']).gte('expires_at',new Date().toISOString()).order('updated_at',{ascending:false}).limit(50);const sessions=uniqueNewest((data||[]) as Session[]);setPending(sessions);if(!sessions.length){setPendingTurns({});return}const ids=sessions.map(x=>x.id);const {data:ts}=await s.from('game_turns').select('*').in('session_id',ids).order('created_at',{ascending:true}).order('id',{ascending:true});const map:Record<string,Turn[]>={};sessions.forEach(x=>map[x.id]=[]);(ts||[]).forEach((t:any)=>(map[t.session_id]??=[]).push(t as Turn));setPendingTurns(map)}
 async function loadTurns(id:string){const {data}=await s.from('game_turns').select('*').eq('session_id',id).order('created_at',{ascending:true}).order('id',{ascending:true});setTurns((data||[]) as Turn[])}
 async function recentIndices(g:GameDef,key:string){const {data}=await s.from('game_sessions').select('state').eq('couple_id',coupleId).eq('game_type',g.id).eq('status','finished').order('finished_at',{ascending:false}).limit(5);const out:number[]=[];(data||[]).forEach((row:any)=>{const v=row.state?.[key];if(Array.isArray(v))v.forEach((x:any)=>Number.isInteger(Number(x))&&out.push(Number(x)));else if(Number.isInteger(Number(v)))out.push(Number(v))});return out}
 async function initialState(g:GameDef){const seed=crypto.randomUUID(),target=targetRounds(g);if(CHOICE_QUESTIONS[g.id]){const avoid=await recentIndices(g,'question_indices');return{question_indices:sampleIndices(CHOICE_QUESTIONS[g.id].length,target,avoid),round_target:target,seed}}if(g.id==='mind-meld'){const avoid=await recentIndices(g,'prompt_indices');return{prompt_indices:sampleIndices(MIND_PROMPTS.length,target,avoid),round_target:target,seed}}if(g.id.startsWith('trivia')){const avoid=await recentIndices(g,'question_indices');return{question_indices:sampleTriviaIndices(target,avoid),round_target:target,seed}}if(g.id==='cards'){const avoid=await recentIndices(g,'card_index');return{card_index:sampleIndices(CARD_DECK.length,1,avoid)[0],seed}}if(g.id==='truth-dare'||g.id==='roulette'){const avoid=await recentIndices(g,'card_index');return{card_index:sampleIndices(TRUTH_DARES.length,1,avoid)[0],seed}}if(g.id==='draw'){const avoid=await recentIndices(g,'word_index');const word_index=sampleIndices(DRAW_WORDS.length,1,avoid)[0];return{word:DRAW_WORDS[word_index],word_index,seed}}if(g.id==='taboo'){const avoid=await recentIndices(g,'taboo_index');const taboo_index=sampleIndices(TABOO_CARDS.length,1,avoid)[0];return{...TABOO_CARDS[taboo_index],taboo_index,seed}}if(g.id==='word-chain'){const starts=['CASA','LUNA','RÍO','MESA','SOL','PANDA','PLAYA','NUBE','CAFÉ','LIBRO','VIAJE','PERÚ','MÚSICA','FOTO','PARQUE','TREN','ISLA','BOSQUE','FLOR','MAR','CIELO','ROBOT','GATO','PERRO','PIZZA','CINE','JUEGO','RUTA','SUEÑO','COLOR','ARTE','AGUA','FUEGO','VIENTO','TIERRA','NOCHE','DÍA','CAMINO','PUENTE','TORRE'];const avoid=await recentIndices(g,'word_index');const word_index=sampleIndices(starts.length,1,avoid)[0];return{word:starts[word_index],word_index,turn_target:10,seed}};if(g.id==='code4')return{secret:Array.from({length:4},(_,i)=>hashIndex(seed+i,6)),seed};if(g.id==='puzzle')return{tiles:[1,2,3,4,5,6,0,7,8],seed};if(g.id==='adventure')return{adventure_id:ADVENTURES[hashIndex(seed,ADVENTURES.length)].id,seed};if(g.id==='escape')return{escape_id:ESCAPES[hashIndex(seed,ESCAPES.length)].id,seed};if(g.id==='block-drop')return{board:Array(25).fill(0),seed};return{seed}}
 async function startGame(g:GameDef){setMessage('');const existing=pending.find(p=>p.game_type===g.id);if(existing){setMessage(`Ya tienen una partida de ${g.title} abierta. La continuamos.`);await openSession(existing);return}if(g.mode==='live'&&!presence)setMessage(`${g.title} es en vivo. La sala quedará lista y puedes esperar a ${partnerName}.`);setBusy(true);const state=await initialState(g);const {data,error}=await s.rpc('start_game_session',{p_game_type:g.id,p_mode:g.mode,p_state:state});setBusy(false);if(error){setMessage('No pudimos abrir la partida: '+error.message);return}const ss=data as Session;setSelected(g);setSession(ss);await loadTurns(ss.id);await loadPending()}
 async function openSession(ss:Session){setSession(ss);setSelected(gameBy(ss.game_type));await loadTurns(ss.id)}
 async function addTurn(action_type:string,payload:any){if(!session)return false;setMessage('');const {error}=await s.rpc('submit_game_turn',{p_session_id:session.id,p_action_type:action_type,p_payload:payload});if(error){const text=(error.message||'').toUpperCase();setMessage(text.includes('WAIT_FOR_PARTNER')?`Ahora le toca a ${partnerName}.`:text.includes('ALREADY_ANSWERED')?'Tu respuesta de esta ronda ya quedó guardada.':'No pudimos guardar el turno: '+error.message);return false}await loadTurns(session.id);await loadPending();return true}
 async function finish(){if(!session)return;setBusy(true);setMessage('');const finishedGame=selected;const {data,error}=await s.rpc('finish_game_session',{p_session_id:session.id});setBusy(false);if(error){const text=(error.message||'').toUpperCase();setMessage(text.includes('WAIT_FOR_PARTNER')?`Falta la participación de ${partnerName}.`:text.includes('PLAY_A_LITTLE_LONGER')?'Jueguen un poquito más antes de cerrar la partida.':'La partida todavía no cumple las condiciones para terminar: '+error.message);return}onPoints?.(Number(data||0));setLastFinished(finishedGame);setSession(null);setSelected(null);setTurns([]);setView('home');await loadPending();await loadWallet()}
 async function abandon(){if(!session)return;if(!confirm('¿Eliminar esta partida? Se cerrará para ambos y no dará puntos.'))return;await s.rpc('abandon_game_session',{p_session_id:session.id});setSession(null);setSelected(null);setTurns([]);setView('pending');await loadPending()}
 async function removePending(ss:Session){if(!confirm(`¿Eliminar la partida de ${gameBy(ss.game_type).title}? Se cerrará para ambos.`))return;const {error}=await s.rpc('abandon_game_session',{p_session_id:ss.id});if(error){setMessage('No pudimos eliminarla: '+error.message);return}if(session?.id===ss.id){setSession(null);setSelected(null);setTurns([])}await loadPending()}
 const myTurnCount=pending.filter(p=>turnBadge(p,pendingTurns[p.id]||[],userId)==='Tu turno').length
 const activeByGame=Object.fromEntries(pending.map(p=>[p.game_type,p])) as Record<string,Session>
 if(session&&selected)return <GameRoom game={selected} session={session} turns={turns} userId={userId} partnerName={partnerName} message={message} busy={busy} onTurn={addTurn} onFinish={finish} onBack={()=>{setSession(null);setSelected(null);setTurns([]);setMessage('')}} onAbandon={abandon}/>
 const shown=GAME_CATALOG.filter(g=>filter==='all'||(filter==='async'&&(g.mode==='async'||g.mode==='both'))||(filter==='live'&&(g.mode==='live'||g.mode==='both'))||(filter==='versus'&&VERSUS_IDS.has(g.id))||(filter==='coop'&&COOP_IDS.has(g.id)))
 const featuredTurn=pending.find(p=>turnBadge(p,pendingTurns[p.id]||[],userId)==='Tu turno')||pending[0]
 return <div className="game-shell game-hub-v9">
  <section className="arcade-hero"><div className="arcade-copy"><span className="arcade-kicker">PANDALANDIA PLAY</span><h1>¿Qué jugamos hoy?</h1><p>Partidas rápidas, retos para dos y juegos en vivo. Todo en un solo lugar.</p><div className="arcade-hero-actions"><button className="btn game-primary" onClick={()=>setView('solo')}>🎮 Jugar solo</button><button className="btn secondary" onClick={()=>setView('catalog')}>Explorar juegos</button></div></div><div className="player-panel"><div className="player-orb">🎮</div><div><small>{wallet?.pet_name?`Para ${wallet.pet_name}`:'Recursos del mundo'}</small>{wallet?<><b>🪙 {wallet.coins.toLocaleString('es-PE')}</b><span>Nivel {wallet.level} · {wallet.xp.toLocaleString('es-PE')} XP</span></>:walletError?<><b>⚠️ Recursos no disponibles</b><span>{walletError} · toca para reintentar</span></>:<><b>🪙 —</b><span>XP — · cargando…</span></>}</div>{walletError&&<button className="wallet-retry" onClick={loadWallet} aria-label="Reintentar cargar recursos">↻</button>}<div className={`presence ${presence?'online':''}`}><i/>{presence?`${partnerName} está en línea`:`${partnerName} puede jugar después`}</div></div></section>
  {message&&<div className="notice">{message}</div>}
  {turnToast&&<div className="turn-toast" role="status">{turnToast}<button onClick={()=>setView('pending')}>Ver turno</button></div>}
  <nav className="game-subnav arcade-tabs"><button className={view==='home'?'active':''} onClick={()=>setView('home')}>🏠 Inicio</button><button className={view==='solo'?'active':''} onClick={()=>setView('solo')}>🎮 Solo</button><button className={view==='catalog'?'active':''} onClick={()=>setView('catalog')}>🕹️ Juegos</button><button className={view==='pending'?'active':''} onClick={()=>setView('pending')}>🔔 Turnos <b>{myTurnCount>0?myTurnCount:pending.length}</b></button></nav>
  {view==='home'&&<>
   {featuredTurn&&<section className={`continue-hero ${turnBadge(featuredTurn,pendingTurns[featuredTurn.id]||[],userId)==='Tu turno'?'hot':''}`}><div className="continue-icon">{gameBy(featuredTurn.game_type).emoji}</div><div className="continue-copy"><span>{playLabel(gameBy(featuredTurn.game_type))}</span><h2>{turnBadge(featuredTurn,pendingTurns[featuredTurn.id]||[],userId)==='Tu turno'?'¡Te toca!':'Partida en curso'}</h2><p><b>{gameBy(featuredTurn.game_type).title}</b> · {progressText(featuredTurn,pendingTurns[featuredTurn.id]||[])}</p></div><button className="btn" onClick={()=>openSession(featuredTurn)}>{turnBadge(featuredTurn,pendingTurns[featuredTurn.id]||[],userId)==='Tu turno'?'Continuar →':'Ver partida'}</button></section>}
   {lastFinished&&<section className="replay-banner"><div><span className="tag">🏆 PARTIDA TERMINADA</span><h2>{lastFinished.emoji} {lastFinished.title}</h2><p>La revancha crea una partida nueva con contenido distinto.</p></div><div className="actions"><button className="btn" onClick={()=>startGame(lastFinished)}>↻ Revancha</button><button className="btn secondary" onClick={()=>{setLastFinished(null);setView('catalog')}}>Cambiar juego</button></div></section>}
   <section className="mode-lanes"><button onClick={()=>setView('solo')}><span>🎮</span><div><b>Jugar solo</b><small>Completa partidas y gana monedas</small></div><em>8 juegos →</em></button><button onClick={()=>{setFilter('versus');setView('catalog')}}><span>⚔️</span><div><b>1 vs 1</b><small>Duelo directo contra {partnerName}</small></div><em>Competir →</em></button><button onClick={()=>{setFilter('async');setView('catalog')}}><span>❤️</span><div><b>Por turnos</b><small>No necesitan coincidir conectados</small></div><em>Jugar →</em></button><button onClick={()=>{setFilter('coop');setView('catalog')}}><span>🤝</span><div><b>Cooperativos</b><small>Los dos contra el juego</small></div><em>Equipo →</em></button><button onClick={()=>{setFilter('live');setView('catalog')}}><span>⚡</span><div><b>En vivo</b><small>Para cuando ambos están online</small></div><em>Entrar →</em></button></section>
   {pending.length>0&&<section className="continue-section"><div className="section-title"><div><span className="arcade-section-kicker">CONTINÚA JUGANDO</span><h2>Partidas abiertas</h2></div><button onClick={()=>setView('pending')}>Ver todas →</button></div><div className="pending-rail">{pending.slice(0,4).map(p=><PendingCard key={p.id} session={p} turns={pendingTurns[p.id]||[]} badge={turnBadge(p,pendingTurns[p.id]||[],userId)} partnerName={partnerName} onOpen={()=>openSession(p)} onDelete={()=>removePending(p)}/>)}</div></section>}
   <section><div className="section-title"><div><span className="arcade-section-kicker">RECOMENDADOS</span><h2>Elige tu próxima partida</h2></div><button onClick={()=>setView('catalog')}>Todo el catálogo →</button></div><div className="game-grid arcade-grid">{['know-me','trivia-versus','mind-meld','draw','puzzle','reaction'].map(id=>{const g=gameBy(id),ss=activeByGame[id];return <GameCard key={id} game={g} active={!!ss} badge={ss?turnBadge(ss,pendingTurns[ss.id]||[],userId):undefined} onClick={()=>startGame(g)}/>})}</div></section>
   <div className="game-alert-bar compact-alert"><div><b>🔔 Avisos de turno</b><span>Sonido y vibración opcionales cuando {partnerName} responde con la app conectada.</span></div><div className="actions"><button className="btn ghost" onClick={toggleSound}>{soundEnabled?'🔊 ON':'🔇 OFF'}</button><button className="btn secondary" onClick={enableAlerts}>Activar</button></div></div>
  </>}
  {view==='solo'&&<SoloGames onReward={(coins,xp)=>{setWallet(w=>w?({...w,coins:w.coins+coins,xp:w.xp+xp}):w);onPoints?.(xp);loadWallet()}}/>}
  {view==='catalog'&&<><div className="catalog-head"><div><span className="arcade-section-kicker">CATÁLOGO</span><h2>¿Cómo quieren jugar?</h2><p>Cada tarjeta te dice si es individual, por turnos, cooperativa, 1 vs 1 o en vivo antes de entrar.</p></div></div><div className="filters game-mode-filters"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>Todos</button><button className={filter==='versus'?'active':''} onClick={()=>setFilter('versus')}>⚔️ 1 vs 1</button><button className={filter==='async'?'active':''} onClick={()=>setFilter('async')}>❤️ Por turnos</button><button className={filter==='coop'?'active':''} onClick={()=>setFilter('coop')}>🤝 Cooperativos</button><button className={filter==='live'?'active':''} onClick={()=>setFilter('live')}>⚡ En vivo</button></div><div className="game-grid arcade-grid">{shown.map(g=>{const ss=activeByGame[g.id];return <GameCard key={g.id} game={g} active={!!ss} badge={ss?turnBadge(ss,pendingTurns[ss.id]||[],userId):undefined} onClick={()=>startGame(g)}/>})}</div></>}
  {view==='pending'&&<section className="turn-center"><div className="section-title"><div><span className="arcade-section-kicker">CENTRO DE TURNOS</span><h2>Partidas abiertas</h2><p className="muted">Solo puede existir una partida activa por juego. Si vuelves a tocar un juego, continuarás esta misma sesión.</p></div><button className="btn secondary" onClick={()=>setView('catalog')}>＋ Elegir juego</button></div>{pending.length===0?<div className="empty-state"><div>🕹️</div><h2>Todo al día</h2><p>No tienen partidas pendientes.</p><button className="btn" onClick={()=>setView('catalog')}>Empezar una partida</button></div>:<div className="pending-list game-turn-list">{pending.map(p=><PendingCard key={p.id} session={p} turns={pendingTurns[p.id]||[]} badge={turnBadge(p,pendingTurns[p.id]||[],userId)} partnerName={partnerName} onOpen={()=>openSession(p)} onDelete={()=>removePending(p)}/>)}</div>}</section>}
 </div>
}
function progressText(session:Session,turns:Turn[]){const g=gameBy(session.game_type),p=sessionRoundProgress(g,turns);if(p)return p.completed>=p.target?`${p.target}/${p.target} rondas listas`:`Pregunta ${p.current} de ${p.target}`;if(g.id==='word-chain')return `${turns.filter(t=>t.action_type==='word').length}/10 turnos`;return g.minutes}
function GameCard({game,onClick,badge,active=false}:{game:GameDef;onClick:()=>void|Promise<void>;badge?:string;active?:boolean}){const style=playStyle(game);return <button className={`game-card arcade-game-card accent-${game.accent} style-${style} ${active?'has-session':''}`} onClick={onClick}><div className="card-topline"><span className={`play-kind ${style}`}>{playLabel(game)}</span><small>{game.minutes}</small></div><div className="game-icon mega">{game.emoji}</div><div className="game-card-copy"><h3>{game.title}</h3><p>{game.description}</p></div><div className="card-footer">{active?<b className={badge==='Tu turno'?'turn-hot':'turn-wait'}>{badge==='Tu turno'?'🔴 Tu turno':'⏳ '+badge}</b>:<span>+{game.points} XP</span>}<em>{active?'CONTINUAR':'JUGAR'} →</em></div></button>}
function PendingCard({session,turns,badge,partnerName,onOpen,onDelete}:{session:Session;turns:Turn[];badge:string;partnerName:string;onOpen:()=>void|Promise<void>;onDelete:()=>void|Promise<void>}){const game=gameBy(session.game_type);return <article className={`pending-card arcade-pending ${badge==='Tu turno'?'my-turn':''}`}><button className="pending-main" onClick={onOpen}><span className="game-icon">{game.emoji}</span><span><small>{playLabel(game)}</small><b>{game.title}</b><em>{badge==='Tu turno'?'🔴 Tu turno':badge==='Listo para cerrar'?'🏁 Resultado listo':`⏳ Esperando a ${partnerName}`}</em><i>{progressText(session,turns)}</i></span></button><div className="pending-actions"><button onClick={onOpen}>{badge==='Tu turno'?'Continuar':'Abrir'}</button><button className="danger" onClick={onDelete}>Eliminar</button></div></article>}

type GameRoomProps={game:GameDef;session:Session;turns:Turn[];userId:string;partnerName:string;message:string;busy:boolean;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>;onBack:()=>void;onAbandon:()=>Promise<void>}
function GameRoom({game,session,turns,userId,partnerName,message,busy,onTurn,onFinish,onBack,onAbandon}:GameRoomProps){
 const mine=turns.filter(t=>t.user_id===userId),theirs=turns.filter(t=>t.user_id!==userId),progress=sessionRoundProgress(game,turns)
 const top=<div className="game-room-top game-room-top-v9"><button className="round-back" onClick={onBack}>← Juegos</button><div className="room-game-id"><span>{game.emoji}</span><div><b>{game.title}</b><small>{playLabel(game)}{progress?` · ${progress.current}/${progress.target}`:''}</small></div></div><div className="room-top-actions"><button className="round-finish" onClick={onAbandon}>Eliminar partida</button></div></div>
 const wrap=(child:React.ReactNode)=><div className="game-room">{top}{message&&<div className="notice room-notice">{message}</div>}{progress&&<div className="round-progress"><span style={{width:`${Math.min(100,(progress.completed/progress.target)*100)}%`}}/><b>{progress.completed>=progress.target?'Partida completa':`Ronda ${progress.current} de ${progress.target}`}</b></div>}{child}</div>
 if(CHOICE_QUESTIONS[game.id])return <MultiRoundChoice game={game} session={session} turns={turns} userId={userId} partnerName={partnerName} busy={busy} top={top} message={message} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='mind-meld')return <MultiRoundText game={game} session={session} turns={turns} userId={userId} partnerName={partnerName} top={top} message={message} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='trivia-coop'||game.id==='trivia-versus')return <MultiRoundTrivia game={game} session={session} turns={turns} userId={userId} partnerName={partnerName} busy={busy} top={top} message={message} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='cards'){const c=CARD_DECK[(session.state?.card_index??0)%CARD_DECK.length];return wrap(<div className="card-stage"><div className="play-card"><span>{c.type}</span><p>{c.text}</p><small>Háganlo a su ritmo. No hay respuesta correcta.</small></div><button className="btn" disabled={busy} onClick={async()=>{await onTurn('complete',{card:c.type});await onFinish()}}>Hecho</button></div>)}
 if(game.id==='draw')return <DrawRoom top={top} message={message} session={session} mine={mine} theirs={theirs} userId={userId} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='two-truths')return <TwoTruths top={top} message={message} mine={mine} theirs={theirs} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='taboo')return <Taboo top={top} message={message} state={session.state} mine={mine} theirs={theirs} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='word-chain')return <WordChain top={top} message={message} start={session.state?.word||'CASA'} turns={turns} userId={userId} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='code4')return <Code4 top={top} message={message} secret={session.state?.secret||[1,2,3,4]} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='puzzle')return <Puzzle top={top} message={message} turns={turns} userId={userId} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='block-drop')return <BlockDrop top={top} message={message} turns={turns} userId={userId} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='adventure')return <AdventureRoom top={top} message={message} session={session} turns={turns} userId={userId} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='escape')return <EscapeRoom top={top} message={message} session={session} turns={turns} userId={userId} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='truth-dare'||game.id==='roulette')return <Roulette top={top} message={message} truth={game.id==='truth-dare'} cardIndex={session.state?.card_index||0} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='reaction')return <ReactionRoom top={top} message={message} mine={mine} theirs={theirs} partnerName={partnerName} onTurn={onTurn} onFinish={onFinish}/>
 if(game.id==='pong')return wrap(<div className="round-card wide"><span className="duel-banner">⚔️ 1 VS 1 · PONG DUO</span><LivePong sessionId={session.id} userId={userId} hostId={session.created_by} partnerName={partnerName}/><button className="btn" onClick={async()=>{await onTurn('complete',{mode:'live'});await onFinish()}}>Terminar partida</button></div>)
 if(game.id==='air-hockey')return wrap(<div className="round-card wide"><span className="duel-banner">⚔️ 1 VS 1 · AIR HOCKEY</span><LiveAirHockey sessionId={session.id} userId={userId} hostId={session.created_by} partnerName={partnerName}/><button className="btn" onClick={async()=>{await onTurn('complete',{mode:'live'});await onFinish()}}>Terminar partida</button></div>)
 if(game.id==='snake-duo')return wrap(<div className="round-card wide"><span className="duel-banner">🤝 COOPERATIVO · EN VIVO</span><LiveSnakeDuo sessionId={session.id} userId={userId} hostId={session.created_by} partnerName={partnerName}/><button className="btn" onClick={async()=>{await onTurn('complete',{mode:'live'});await onFinish()}}>Terminar partida</button></div>)
 if(game.id==='turbo-race')return wrap(<div className="round-card wide"><span className="duel-banner">⚔️ 1 VS 1 · TURBO RACE</span><LiveTurboRace sessionId={session.id} userId={userId} partnerName={partnerName}/><button className="btn" onClick={async()=>{await onTurn('complete',{mode:'live'});await onFinish()}}>Terminar partida</button></div>)
 if(game.id==='bomb')return <Bomb top={top} message={message} onTurn={onTurn} onFinish={onFinish}/>
 return wrap(<div className="round-card"><h2>{game.title}</h2><p>Juego listo en el motor común.</p></div>)
}
function roundAnswer(ts:Turn[],uid:string,action:string,round:number){return ts.find(t=>t.user_id===uid&&t.action_type===action&&Number(t.payload?.round||1)===round)}
function completedRoundPairs(ts:Turn[],action:string,target:number){let n=0;for(let r=1;r<=target;r++){if(new Set(ts.filter(t=>t.action_type===action&&Number(t.payload?.round||1)===r).map(t=>t.user_id)).size>=2)n++;else break}return n}
function RoundShell({top,message,current,target,children}:{top:React.ReactNode;message:string;current:number;target:number;children:React.ReactNode}){const done=Math.min(target,current-1);return <div className="game-room">{top}<Notice message={message}/><div className="round-progress"><span style={{width:`${Math.round(done/target*100)}%`}}/><b>{done>=target?`${target}/${target} completadas`:`Pregunta ${current} de ${target}`}</b></div>{children}</div>}
function MultiRoundChoice({game,session,turns,userId,partnerName,busy,top,message,onTurn,onFinish}:{game:GameDef;session:Session;turns:Turn[];userId:string;partnerName:string;busy:boolean;top:React.ReactNode;message:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const target=targetRounds(game),completed=completedRoundPairs(turns,'choice',target),round=Math.min(target,completed+1),indices:Array<number>=session.state?.question_indices||[session.state?.question_index||0],list=CHOICE_QUESTIONS[game.id],q=list[(indices[round-1]??indices[0]??0)%list.length],mine=roundAnswer(turns,userId,'choice',round),other=turns.find(t=>t.user_id!==userId&&t.action_type==='choice'&&Number(t.payload?.round||1)===round);const lastRound=completed>0?completed:0,lastMine=lastRound?roundAnswer(turns,userId,'choice',lastRound):undefined,lastOther=lastRound?turns.find(t=>t.user_id!==userId&&t.action_type==='choice'&&Number(t.payload?.round||1)===lastRound):undefined;const matches=Array.from({length:completed},(_,i)=>{const r=i+1,a=roundAnswer(turns,userId,'choice',r),b=turns.find(t=>t.user_id!==userId&&t.action_type==='choice'&&Number(t.payload?.round||1)===r);return a?.payload?.choice===b?.payload?.choice}).filter(Boolean).length;if(completed>=target)return <RoundShell top={top} message={message} current={target+1} target={target}><div className="round-card game-complete"><div className="reveal-burst">🏆</div><span className="tag">PARTIDA COMPLETADA</span><h2>{game.id==='know-me'?`${matches} de ${target} coincidencias`:`${matches} de ${target} coincidencias`}</h2><p>Terminaron todas las preguntas de esta partida. La próxima usará otro conjunto siempre que haya disponibles.</p><div className="match-meter"><span style={{width:`${matches/target*100}%`}}/></div><button className="btn" onClick={onFinish}>Ver resultado y cobrar XP</button></div></RoundShell>;const isKnow=game.id==='know-me',aboutMe=isKnow?((round%2===1&&session.created_by===userId)||(round%2===0&&session.created_by!==userId)):false;return <RoundShell top={top} message={message} current={round} target={target}><div className="round-card">{lastMine&&lastOther&&<div className={`last-round ${lastMine.payload.choice===lastOther.payload.choice?'match':''}`}><b>{lastMine.payload.choice===lastOther.payload.choice?'✨ Coincidieron en la anterior':'👀 Respuestas distintas en la anterior'}</b><span>La partida avanzó automáticamente.</span></div>}<span className="tag">{isKnow?(aboutMe?'🙋 Responde por ti':'🔎 Adivina qué elegiría '+partnerName):'🔒 Se revela cuando ambos respondan'}</span><h2>{q.q}</h2><div className="choice-grid">{q.options.map(o=>{const label=o==='Mi persona'||o==='Tu persona'?partnerName:o;return <button key={o} disabled={!!mine||busy} className={mine?.payload?.choice===o?'chosen':''} onClick={()=>onTurn('choice',{choice:o,round})}>{label}</button>})}</div>{mine&&!other&&<Waiting name={partnerName}/>} {!mine&&other&&<div className="partner-ready">💌 {partnerName} ya respondió esta pregunta. Falta tu elección.</div>}</div></RoundShell>}
function MultiRoundText({game,session,turns,userId,partnerName,top,message,onTurn,onFinish}:{game:GameDef;session:Session;turns:Turn[];userId:string;partnerName:string;top:React.ReactNode;message:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const target=targetRounds(game),completed=completedRoundPairs(turns,'text',target),round=Math.min(target,completed+1),indices:Array<number>=session.state?.prompt_indices||[session.state?.prompt_index||0],prompt=MIND_PROMPTS[(indices[round-1]??0)%MIND_PROMPTS.length],mine=roundAnswer(turns,userId,'text',round),other=turns.find(t=>t.user_id!==userId&&t.action_type==='text'&&Number(t.payload?.round||1)===round),matches=Array.from({length:completed},(_,i)=>{const r=i+1,a=roundAnswer(turns,userId,'text',r),b=turns.find(t=>t.user_id!==userId&&t.action_type==='text'&&Number(t.payload?.round||1)===r);return normalize(a?.payload?.text||'')===normalize(b?.payload?.text||'')}).filter(Boolean).length;const [text,setText]=useState('');if(completed>=target)return <RoundShell top={top} message={message} current={target+1} target={target}><div className="round-card game-complete"><div className="reveal-burst">🧠</div><h2>{matches} coincidencias de {target}</h2><p>Mentes conectadas completado.</p><button className="btn" onClick={onFinish}>Terminar partida</button></div></RoundShell>;return <RoundShell top={top} message={message} current={round} target={target}><div className="round-card"><span className="tag">🧠 Escriban sin ver la respuesta del otro</span><h2>{prompt}</h2>{!mine&&<><input className="game-input" maxLength={80} value={text} onChange={e=>setText(e.target.value)} placeholder="Una palabra…"/><button className="btn" disabled={!text.trim()} onClick={async()=>{if(await onTurn('text',{text:text.trim(),round}))setText('')}}>Bloquear respuesta</button></>}{mine&&!other&&<Waiting name={partnerName}/>} {!mine&&other&&<div className="partner-ready">💌 {partnerName} ya respondió. Te toca.</div>}</div></RoundShell>}
function MultiRoundTrivia({game,session,turns,userId,partnerName,busy,top,message,onTurn,onFinish}:{game:GameDef;session:Session;turns:Turn[];userId:string;partnerName:string;busy:boolean;top:React.ReactNode;message:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const target=targetRounds(game),completed=completedRoundPairs(turns,'trivia',target),round=Math.min(target,completed+1),indices:Array<number>=session.state?.question_indices||[session.state?.question_index||0],q=TRIVIA[(indices[round-1]??0)%TRIVIA.length],mine=roundAnswer(turns,userId,'trivia',round),other=turns.find(t=>t.user_id!==userId&&t.action_type==='trivia'&&Number(t.payload?.round||1)===round);let myScore=0,otherScore=0;for(let r=1;r<=completed;r++){const qi=TRIVIA[(indices[r-1]??0)%TRIVIA.length],a=roundAnswer(turns,userId,'trivia',r),b=turns.find(t=>t.user_id!==userId&&t.action_type==='trivia'&&Number(t.payload?.round||1)===r);if(Number(a?.payload?.answer)===qi.a)myScore++;if(Number(b?.payload?.answer)===qi.a)otherScore++}const lastRound=completed>0?completed:0,lastQ=lastRound?TRIVIA[(indices[lastRound-1]??0)%TRIVIA.length]:null,lastMine=lastRound?roundAnswer(turns,userId,'trivia',lastRound):undefined,lastOther=lastRound?turns.find(t=>t.user_id!==userId&&t.action_type==='trivia'&&Number(t.payload?.round||1)===lastRound):undefined;const feedback=lastQ&&lastMine&&lastOther?<div className="trivia-pair-feedback"><b>Resultado de la pregunta anterior</b><p>{lastQ.q.replace(/ #\d+$/,'')}</p><div className="trivia-answer-row"><span className={Number(lastMine.payload.answer)===lastQ.a?'ok':'bad'}>Tú: <strong>{lastQ.o[Number(lastMine.payload.answer)]}</strong></span><span className={Number(lastOther.payload.answer)===lastQ.a?'ok':'bad'}>{partnerName}: <strong>{lastQ.o[Number(lastOther.payload.answer)]}</strong></span></div><div className="correct-answer-line">✅ Correcta: <strong>{lastQ.o[lastQ.a]}</strong></div></div>:null;if(completed>=target)return <RoundShell top={top} message={message} current={target+1} target={target}><div className="round-card game-complete"><div className="reveal-burst">{game.id==='trivia-versus'?'⚔️':'🤝'}</div><h2>{game.id==='trivia-versus'?(myScore===otherScore?'¡Empate!':myScore>otherScore?'¡Ganaste el duelo!':`Ganó ${partnerName}`):`Equipo: ${myScore+otherScore} aciertos`}</h2>{feedback}<div className="duel-score"><span><small>TÚ</small><b>{myScore}</b></span><i>—</i><span><small>{partnerName}</small><b>{otherScore}</b></span></div><button className="btn" onClick={onFinish}>Cerrar partida</button></div></RoundShell>;return <RoundShell top={top} message={message} current={round} target={target}><div className="round-card">{feedback}<div className="trivia-scoreline"><span>{game.id==='trivia-versus'?'⚔️ 1 VS 1':'🤝 COOPERATIVO'}</span><b>{myScore} — {otherScore}</b></div><span className="tag">{q.cat}</span><h2>{q.q.replace(/ #\d+$/,'')}</h2><div className="choice-grid">{q.o.map((o,i)=><button key={o} disabled={!!mine||busy} className={Number(mine?.payload?.answer)===i?'chosen':''} onClick={()=>onTurn('trivia',{answer:i,round})}>{o}</button>)}</div>{mine&&!other&&<Waiting name={partnerName}/>} {!mine&&other&&<div className="partner-ready">⚔️ {partnerName} ya respondió. Tu respuesta sigue oculta hasta enviarla.</div>}</div></RoundShell>}

function Waiting({name}:{name:string}){return <div className="waiting"><div className="typing"><i/><i/><i/></div><div><b>Tu turno quedó guardado</b><p>Esperando a {name}. Puede responder más tarde.</p></div></div>}
function Reveal({a,b,match,onFinish,partnerName='Tu compañero/a'}:{a:any;b:any;match:boolean;onFinish:()=>Promise<void>;partnerName?:string}){return <div className="reveal"><div className="reveal-burst">{match?'✨':'👀'}</div><h3>{match?'¡Coincidieron!':'Pensaron diferente'}</h3><div className="versus-answer"><span>Tú<b>{String(a)}</b></span><span>{partnerName}<b>{String(b)}</b></span></div><button className="btn" onClick={onFinish}>Cerrar ronda</button></div>}
function Notice({message}:{message:string}){return message?<div className="notice room-notice">{message}</div>:null}

function DrawRoom({top,message,session,mine,theirs,userId,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;session:Session;mine:Turn[];theirs:Turn[];userId:string;partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const [strokes,setStrokes]=useState<Stroke[]>([]),[guess,setGuess]=useState('');const drawingTurn=turnsByAction([...mine,...theirs],'drawing')[0];const drawing=drawingTurn?.payload?.strokes;const myGuess=mine.find(t=>t.action_type==='guess');const otherGuess=theirs.find(t=>t.action_type==='guess');if(!drawing)return <div className="game-room">{top}<Notice message={message}/><div className="round-card wide"><span className="tag">Tu palabra: {session.state?.word}</span><h2>Dibújalo sin letras</h2><DrawingBoard value={strokes} onChange={setStrokes}/><button className="btn" disabled={strokes.length<2} onClick={()=>onTurn('drawing',{strokes})}>Enviar dibujo</button></div></div>;const amDrawer=drawingTurn.user_id===userId; if(!amDrawer&&!myGuess)return <div className="game-room">{top}<Notice message={message}/><div className="round-card wide"><h2>¿Qué dibujó {partnerName}?</h2><DrawingBoard value={drawing} readonly/><input className="game-input" value={guess} maxLength={50} onChange={e=>setGuess(e.target.value)} placeholder="Tu respuesta"/><button className="btn" disabled={!guess.trim()} onClick={()=>onTurn('guess',{guess:guess.trim()})}>Adivinar</button></div></div>;if(amDrawer&&!otherGuess)return <div className="game-room">{top}<Notice message={message}/><div className="round-card wide"><DrawingBoard value={drawing} readonly/><Waiting name={partnerName}/></div></div>;const guessTurn=myGuess||otherGuess;const ok=normalize(guessTurn?.payload?.guess||'')===normalize(session.state?.word||'');return <div className="game-room">{top}<Notice message={message}/><div className="round-card wide"><DrawingBoard value={drawing} readonly/><div className="reveal"><div className="reveal-burst">{ok?'🎯':'🎨'}</div><h3>{ok?'¡Adivinado!':'La palabra era '+session.state?.word}</h3><p>Respuesta: <b>{guessTurn?.payload?.guess}</b></p><button className="btn" onClick={onFinish}>Terminar</button></div></div></div>}
function turnsByAction(ts:Turn[],a:string){return ts.filter(t=>t.action_type===a)}

function TwoTruths({top,message,mine,theirs,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;mine:Turn[];theirs:Turn[];partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const [vals,setVals]=useState(['','','']),[lie,setLie]=useState(2);const mineCreated=mine.find(t=>t.action_type==='statements'),otherCreated=theirs.find(t=>t.action_type==='statements'),myGuess=mine.find(t=>t.action_type==='guess'),otherGuess=theirs.find(t=>t.action_type==='guess');if(!mineCreated&&!otherCreated)return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>Escribe dos verdades y una mentira</h2>{vals.map((v,i)=><div className="statement-row" key={i}><input maxLength={160} value={v} onChange={e=>{const n=[...vals];n[i]=e.target.value;setVals(n)}} placeholder={`Afirmación ${i+1}`}/><label><input type="radio" checked={lie===i} onChange={()=>setLie(i)}/> mentira</label></div>)}<button className="btn" disabled={vals.some(v=>!v.trim())} onClick={()=>onTurn('statements',{items:vals.map(v=>v.trim()),lie})}>Enviar</button></div></div>;if(otherCreated&&!myGuess)return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>¿Cuál es la mentira de {partnerName}?</h2><div className="choice-grid">{otherCreated.payload.items.map((x:string,i:number)=><button key={i} onClick={()=>onTurn('guess',{index:i})}>{x}</button>)}</div></div></div>;if(mineCreated&&!otherGuess)return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><Waiting name={partnerName}/></div></div>;const guess=myGuess||otherGuess,target=myGuess?otherCreated:mineCreated;const match=!!guess&&!!target&&guess.payload.index===target.payload.lie;return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><Reveal a={`Elegiste ${Number(guess?.payload?.index)+1}`} b={`Era ${Number(target?.payload?.lie)+1}`} match={match} onFinish={onFinish} partnerName={partnerName}/></div></div>}

function Taboo({top,message,state,mine,theirs,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;state:any;mine:Turn[];theirs:Turn[];partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const [hint,setHint]=useState(''),[guess,setGuess]=useState('');const myHint=mine.find(t=>t.action_type==='hint'),otherHint=theirs.find(t=>t.action_type==='hint'),myGuess=mine.find(t=>t.action_type==='guess'),otherGuess=theirs.find(t=>t.action_type==='guess');if(!myHint&&!otherHint)return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><span className="tag">Palabra: {state.word}</span><h2>Da una pista</h2><p className="muted">No uses: {(state.forbidden||[]).join(', ')}</p><input className="game-input" maxLength={160} value={hint} onChange={e=>setHint(e.target.value)}/><button className="btn" disabled={!hint.trim()||state.forbidden?.some((x:string)=>normalize(hint).includes(normalize(x)))} onClick={()=>onTurn('hint',{hint:hint.trim()})}>Enviar pista</button></div></div>;if(otherHint&&!myGuess)return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>Pista de {partnerName}</h2><div className="clue">“{otherHint.payload.hint}”</div><input className="game-input" maxLength={60} value={guess} onChange={e=>setGuess(e.target.value)}/><button className="btn" disabled={!guess.trim()} onClick={()=>onTurn('guess',{guess:guess.trim()})}>Responder</button></div></div>;if(myHint&&!otherGuess)return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><Waiting name={partnerName}/></div></div>;const g=myGuess||otherGuess;return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><Reveal a={g?.payload?.guess||''} b={state.word} match={normalize(g?.payload?.guess||'')===normalize(state.word)} onFinish={onFinish} partnerName={partnerName}/></div></div>}

function WordChain({top,message,start,turns,userId,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;start:string;turns:Turn[];userId:string;partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const [word,setWord]=useState('');const entries=turns.filter(t=>t.action_type==='word'),words=[start,...entries.map(t=>t.payload.word)],last=words.at(-1)||start,lastUser=entries.at(-1)?.user_id;const myTurn=!lastUser||lastUser!==userId;const clean=word.trim();const valid=clean.length>1&&normalize(clean).startsWith(normalize(last).slice(-1))&&!words.map(normalize).includes(normalize(clean));return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>Cadena de palabras</h2><div className="word-chain">{words.map((w,i)=><span key={i}>{w}</span>)}</div>{myTurn?<><p>Tu palabra debe empezar con <b>{last.slice(-1).toUpperCase()}</b>.</p><input className="game-input" maxLength={40} value={word} onChange={e=>setWord(e.target.value)}/><button className="btn" disabled={!valid} onClick={async()=>{if(await onTurn('word',{word:clean}))setWord('')}}>Agregar</button></>:<Waiting name={partnerName}/>} {entries.length>=10&&<button className="btn secondary" onClick={onFinish}>Terminar 10 turnos</button>}</div></div>}

function Code4({top,message,secret,onTurn,onFinish}:{top:React.ReactNode;message:string;secret:number[];onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const [guess,setGuess]=useState([0,0,0,0]),[tries,setTries]=useState<{g:number[];exact:number;near:number}[]>([]),[sent,setSent]=useState(false);const solved=tries.at(-1)?.exact===4;function test(){let exact=0;const sc=[...secret],gc=[...guess];for(let i=0;i<4;i++)if(gc[i]===sc[i]){exact++;gc[i]=-1;sc[i]=-2}let near=0;for(let i=0;i<4;i++){if(gc[i]<0)continue;const j=sc.indexOf(gc[i]);if(j>=0){near++;sc[j]=-2}}setTries([...tries,{g:[...guess],exact,near}])}async function complete(){if(!sent){await onTurn('complete',{tries:tries.length});setSent(true)}await onFinish()}return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>Descifra el código</h2><p className="muted">● correcto en lugar correcto · ○ correcto en lugar distinto.</p><div className="code-row">{guess.map((v,i)=><button key={i} onClick={()=>{const n=[...guess];n[i]=(v+1)%6;setGuess(n)}}>{v+1}</button>)}</div><button className="btn" onClick={test}>Probar</button><div className="code-tries">{tries.map((t,i)=><div key={i}><span>{t.g.map(x=>x+1).join(' ')}</span><b>{'●'.repeat(t.exact)}{'○'.repeat(t.near)}</b></div>)}</div>{solved&&<button className="btn secondary" onClick={complete}>Código descubierto ✨</button>}</div></div>}

function derivePuzzle(turns:Turn[]){let tiles=[1,2,3,4,5,6,0,7,8];for(const t of turns.filter(x=>x.action_type==='puzzle_move')){const i=Number(t.payload.index),z=tiles.indexOf(0),r=Math.floor(i/3),zr=Math.floor(z/3);if(Number.isInteger(i)&&i>=0&&i<9&&(Math.abs(i-z)===3||(r===zr&&Math.abs(i-z)===1))){const n=[...tiles];[n[i],n[z]]=[n[z],n[i]];tiles=n}}return tiles}
function Puzzle({top,message,turns,userId,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;turns:Turn[];userId:string;partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const tiles=derivePuzzle(turns),moves=turns.filter(t=>t.action_type==='puzzle_move'),last=moves.at(-1)?.user_id,myTurn=!last||last!==userId,solved=tiles.join(',')==='1,2,3,4,5,6,7,8,0';async function move(i:number){const z=tiles.indexOf(0),r=Math.floor(i/3),zr=Math.floor(z/3);if(myTurn&&(Math.abs(i-z)===3||(r===zr&&Math.abs(i-z)===1)))await onTurn('puzzle_move',{index:i})}async function done(){await onTurn('complete',{moves:moves.length});await onFinish()}return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>Puzzle cooperativo 3×3</h2><p className="muted">Cada movimiento se guarda. Después de mover, le toca a {partnerName}.</p><div className="puzzle-grid">{tiles.map((t,i)=><button key={i} disabled={!myTurn||t===0} className={t===0?'blank':''} onClick={()=>move(i)}>{t||''}</button>)}</div>{!myTurn&&!solved&&<Waiting name={partnerName}/>} {solved&&<button className="btn" onClick={done}>¡Completado!</button>}</div></div>}

function BlockDrop({top,message,turns,userId,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;turns:Turn[];userId:string;partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const moves=turns.filter(t=>t.action_type==='block'),filled=new Set<number>(moves.map(t=>Number(t.payload.cell))),last=moves.at(-1)?.user_id,myTurn=!last||last!==userId;const completedRows=[0,1,2,3,4].filter(r=>[0,1,2,3,4].every(c=>filled.has(r*5+c)));async function place(cell:number){if(!filled.has(cell)&&myTurn)await onTurn('block',{cell})}async function done(){await onTurn('complete',{rows:completedRows.length});await onFinish()}return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>Block Drop cooperativo</h2><p>Alternen colocando bloques. Completen al menos una línea horizontal.</p><div className="block-grid">{Array.from({length:25},(_,i)=><button key={i} disabled={!myTurn||filled.has(i)} className={filled.has(i)?'filled':''} onClick={()=>place(i)}/>)}</div>{!myTurn&&<Waiting name={partnerName}/>} {completedRows.length>0&&<button className="btn" onClick={done}>Completar línea ✨</button>}</div></div>}

function AdventureRoom({top,message,session,turns,userId,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;session:Session;turns:Turn[];userId:string;partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const adventure=ADVENTURES.find(a=>a.id===session.state?.adventure_id)||ADVENTURES[0],choices=turns.filter(t=>t.action_type==='adventure_choice'),end=turns.find(t=>t.action_type==='adventure_end');let node=adventure.nodes[adventure.start];for(const t of choices){const choice=node.choices?.[Number(t.payload.index)];if(!choice)break;node=adventure.nodes[choice.next]}const last=choices.at(-1)?.user_id,myTurn=!last||last!==userId;if(end)return <div className="game-room adventure-bg">{top}<Notice message={message}/><div className="story-card"><span>{adventure.subtitle}</span><h2>{node.title}</h2><p>{node.text}</p><div className="ending-badge">{node.ending}</div><button className="btn" onClick={onFinish}>Guardar final</button></div></div>;async function choose(i:number){const next=node.choices?.[i];if(!next)return;const nextNode=adventure.nodes[next.next];await onTurn('adventure_choice',{node:node.id,index:i,next:next.next});if(nextNode.ending)await onTurn('adventure_end',{ending:nextNode.ending,node:nextNode.id})}return <div className="game-room adventure-bg">{top}<Notice message={message}/><div className="story-card"><span>{adventure.title} · decisión {choices.length+1}</span><h2>{node.title}</h2><p>{node.text}</p>{node.choices?.map((o,i)=><button key={o.label} disabled={!myTurn} onClick={()=>choose(i)}>{o.label}<b>→</b></button>)}{!myTurn&&<Waiting name={partnerName}/>}</div></div>}

function EscapeRoom({top,message,session,turns,userId,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;session:Session;turns:Turn[];userId:string;partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const scenario=ESCAPES.find(e=>e.id===session.state?.escape_id)||ESCAPES[0],found=turns.filter(t=>t.action_type==='escape_clue').map(t=>String(t.payload.object)),solved=turns.some(t=>t.action_type==='escape_solved'),[code,setCode]=useState('');async function find(id:string){if(!found.includes(id))await onTurn('escape_clue',{object:id})}async function tryCode(){if(code===scenario.code)await onTurn('escape_solved',{code});else await onTurn('escape_attempt',{length:code.length})}return <div className="game-room escape-bg">{top}<Notice message={message}/><div className="escape-room"><span className="tag">{scenario.subtitle}</span><h2>{scenario.title}</h2>{!solved?<><p>Toquen objetos, compartan pistas y abran el cierre.</p><div className="room-scene escape-objects">{scenario.objects.map(o=><button key={o.id} className={`escape-object ${found.includes(o.id)?'found':''}`} onClick={()=>find(o.id)}><span>{o.emoji}</span><small>{o.name}</small></button>)}<div className="safe">🔒</div></div><div className="inventory">{scenario.objects.filter(o=>found.includes(o.id)).map(o=><span key={o.id}>🔎 {o.clue}</span>)}</div><input className="game-input" inputMode="numeric" maxLength={4} value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,''))} placeholder="Código"/><button className="btn" disabled={code.length<3} onClick={tryCode}>Probar código</button><p className="tiny">Las pistas encontradas quedan visibles para ambos incluso si entran en horas distintas.</p></>:<div className="reveal"><div className="reveal-burst">🗝️</div><h3>¡Sala resuelta!</h3><p>{scenario.finalText}</p><button className="btn" onClick={onFinish}>Cerrar caso</button></div>}</div></div>}

function Roulette({top,message,truth,cardIndex,onTurn,onFinish}:{top:React.ReactNode;message:string;truth:boolean;cardIndex:number;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const options=truth?['Verdad','Reto','Verdad','Reto','Sorpresa','Elige el otro']:['Pregunta','Reto','Comida','Película','Sorpresa','Elección'];const [rot,setRot]=useState(0),[pick,setPick]=useState(''),[text,setText]=useState('');function spin(){const idx=Math.floor(Math.random()*options.length);setRot(r=>r+720+idx*60);setPick('');setTimeout(()=>{setPick(options[idx]);const card=TRUTH_DARES[(cardIndex+idx)%TRUTH_DARES.length];setText(truth?card.text:idx===0?'¿Qué lugar nuevo visitarían este mes?':idx===1?'Hagan una pose absurda durante 15 segundos.':idx===2?'Elijan una comida para compartir.':idx===3?'Elijan una película sin mirar puntuaciones.':'El otro decide la siguiente ronda.')},720)}async function done(){await onTurn('complete',{result:pick});await onFinish()}return <div className="game-room">{top}<Notice message={message}/><div className="round-card roulette-wrap"><div className="roulette-pointer">▼</div><div className="roulette-wheel" style={{transform:`rotate(${rot}deg)`}}>{options.map((o,i)=><span key={o+i} style={{transform:`rotate(${i*60}deg) translateY(-92px) rotate(${-i*60}deg)`}}>{o}</span>)}</div><button className="btn" onClick={spin}>Girar</button>{pick&&<div className="clue"><b>{pick}</b><br/>{text}</div>} {pick&&<button className="btn secondary" onClick={done}>Hecho</button>}</div></div>}

function ReactionRoom({top,message,mine,theirs,partnerName,onTurn,onFinish}:{top:React.ReactNode;message:string;mine:Turn[];theirs:Turn[];partnerName:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const my=mine.find(t=>t.action_type==='reaction')?.payload?.ms,other=theirs.find(t=>t.action_type==='reaction')?.payload?.ms;return <div className="game-room">{top}<Notice message={message}/><div className="round-card"><h2>Reaction Duel</h2>{my===undefined?<ReactionGame onScore={ms=>onTurn('reaction',{ms})}/>:other===undefined?<Waiting name={partnerName}/>:<div className="reveal"><div className="reveal-burst">⚡</div><h3>{my<other?'Ganaste esta ronda':my===other?'Empate perfecto':'Ganó '+partnerName}</h3><div className="versus-answer"><span>Tú<b>{my} ms</b></span><span>{partnerName}<b>{other} ms</b></span></div><button className="btn" onClick={onFinish}>Cerrar duelo</button></div>}</div></div>}

function Bomb({top,message,onTurn,onFinish}:{top:React.ReactNode;message:string;onTurn:(a:string,p:any)=>Promise<boolean>;onFinish:()=>Promise<void>}){const categories=['Países con C','Animales con M','Comidas que llevan queso','Películas de una palabra','Cosas que hay en una cocina','Ciudades de Sudamérica','Objetos rojos','Profesiones'],[category]=useState(()=>categories[Math.floor(Math.random()*categories.length)]),[running,setRunning]=useState(false),[boom,setBoom]=useState(false);useEffect(()=>{if(!running)return;const t=setTimeout(()=>{setBoom(true);setRunning(false);navigator.vibrate?.([120,60,180])},3000+Math.random()*6500);return()=>clearTimeout(t)},[running]);async function done(){await onTurn('complete',{category});await onFinish()}return <div className="game-room">{top}<Notice message={message}/><div className="round-card bomb-card"><div className={boom?'bomb boom':'bomb'}>💣</div><h2>{boom?'¡BOOM!':category}</h2><p>Pásense el turno verbalmente. El temporizador cambia en cada ronda.</p><button className="btn" disabled={running} onClick={()=>{setBoom(false);setRunning(true)}}>{running?'Corriendo…':'Iniciar bomba'}</button>{boom&&<button className="btn secondary" onClick={done}>Terminar</button>}</div></div>}
